def _partially_consume_prefix(self, prefix, column):
    lines = []
    current_line = ""
    current_column = 0
    wait_for_nl = False

    for char in prefix:
        if char == '\n':
            if current_line.strip():
                lines.append(current_line)
            current_line = ""
            current_column = 0
            wait_for_nl = False
        else:
            current_line += char
            if char == ' ':
                current_column += 1
            elif char == '\t':
                current_column += 4
            else:
                wait_for_nl = True

            if wait_for_nl and current_column >= column:
                lines.append(current_line)
                current_line = ""
                current_column = 0
                wait_for_nl = False

    if current_line.strip():
        lines.append(current_line)

    return ''.join(lines), current_line
